        google: { rating: 4.1, review_count: 15, maps_url: 'https://maps.google.com/?cid=14184384150615162220&g_mp=CiVnb29nbGUubWFwcy5wbGFjZXMudjEuUGxhY2VzLkdldFBsYWNlEAIYBCAA', reviews: [{author: 'Alicia Moore', rating: 5, text: 'Knowledgeable and helpful staff. Great owners! They have incense!!!', time: '7 months ago'}, {author: 'Jeremy Neugent', rating: 4, text: 'Nice quality product, a little expensive but im used to California prices, overall a great place to get what you need! Nice staff!', time: '6 months ago'}, {author: 'Greg Schwartz', rating: 1, text: 'Price gouging on carts 1/2 gram $79 is highway robbery anyone with a phone can call any dispensary to check pricing to find this to be true. Grounded gardens would be a better local choice to obtain fair pricing on carts and all other products with a full line of accessories at much lower prices then i have seen anywhere in Hutchenson', time: '2 months ago'}, {author: 'Mark Stachowski', rating: 1, text: 'Not impressed at all and way over priced..', time: '2 months ago'}, {author: 'Rc addict', rating: 4, text: 'Great service quick too but kinda spendy hopefully in the future prices come down with product coming from crosslake', time: '7 months ago'}] }
